INSERT IGNORE INTO rc_screening_sets (code, title, pass_threshold, knockout_groups, questions) VALUES
('IT-STD-8', 'IT engineers — reliability & security mindset (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "security", "text": "A colleague at a shipyard asks you to open a firewall port \\"just for today\\" so a maker can connect remotely. You…", "options": [{"id": "a", "text": "Set up the access properly — VPN or a time-limited rule — and log who, what and until when.", "score": 1}, {"id": "b", "text": "Open it; closing it later is a detail.", "score": 0}, {"id": "c", "text": "Ask what exactly the maker needs and give the narrowest access that does the job.", "score": 1}]}, {"id": "q2", "group": "ops", "text": "The portal is slow on a Monday morning and nobody knows why. Your first move:", "options": [{"id": "a", "text": "Check the metrics and logs, find the change or load that correlates and fix the cause.", "score": 1}, {"id": "b", "text": "Restart everything and see if it goes away.", "score": 0}, {"id": "c", "text": "Reproduce it, measure it, then change one thing at a time.", "score": 1}]}, {"id": "q3", "group": "backup", "text": "How do you know the backups work?", "options": [{"id": "a", "text": "They are restored on a schedule and the restore is documented — an untested backup is a hope, not a backup.", "score": 1}, {"id": "b", "text": "The job says \\"success\\" every night, that is enough.", "score": 0}, {"id": "c", "text": "I restore a sample regularly and keep one copy off-site and offline.", "score": 1}]}, {"id": "q4", "group": "learning", "text": "A new technology (say a new identity standard) becomes relevant to the company. You…", "options": [{"id": "a", "text": "Read the spec, build a small proof of concept and present where it fits.", "score": 1}, {"id": "b", "text": "Wait until a vendor sells it to us.", "score": 0}, {"id": "c", "text": "Evaluate it against our real needs and risks before recommending it.", "score": 1}]}, {"id": "q5", "group": "users", "text": "An engineer on board cannot log in before a sea trial and is stressed. You…", "options": [{"id": "a", "text": "Fix the immediate problem calmly, then find why it happened so it does not repeat.", "score": 1}, {"id": "b", "text": "Tell them to open a ticket and wait their turn.", "score": 0}, {"id": "c", "text": "Get them working within minutes and follow up with a root cause afterwards.", "score": 1}]}, {"id": "q6", "group": "docs", "text": "Documentation and change records for systems you run are…", "options": [{"id": "a", "text": "Part of the job — the next person must be able to operate it without me.", "score": 1}, {"id": "b", "text": "Written when there is time, which is never.", "score": 0}, {"id": "c", "text": "Kept current in the repository with every change.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('MEC-STD-8', 'Mechanical engineers — design & yard mindset (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "design", "text": "A console must hold heavy equipment on a yacht and the owner wants it thinner than your calculation allows. You…", "options": [{"id": "a", "text": "Show the loads and the margin, then offer a design that meets both the look and the strength.", "score": 1}, {"id": "b", "text": "Make it thinner — the owner is always right.", "score": 0}, {"id": "c", "text": "Re-engineer the structure (material, ribs, fixing points) and prove it with the numbers.", "score": 1}]}, {"id": "q2", "group": "yard", "text": "On board, the foundation you designed does not match the steel actually built. You…", "options": [{"id": "a", "text": "Measure as built, adapt the design on the spot where safe and record the deviation.", "score": 1}, {"id": "b", "text": "Insist the yard rebuilds the steel to the drawing regardless of schedule.", "score": 0}, {"id": "c", "text": "Agree the fix with the yard and the class surveyor and update the drawings the same week.", "score": 1}]}, {"id": "q3", "group": "materials", "text": "Choosing between AISI 316 and painted mild steel for a bracket in a Ro-Ro / open-deck space, you…", "options": [{"id": "a", "text": "Pick by environment, class rules and lifetime cost, not by habit.", "score": 1}, {"id": "b", "text": "Pick the cheapest; it is only a bracket.", "score": 0}, {"id": "c", "text": "Check the rules for the space and the owner specification before deciding.", "score": 1}]}, {"id": "q4", "group": "tools", "text": "Your approach to CAD, tolerancing and manufacturing drawings:", "options": [{"id": "a", "text": "Drawings must be buildable by the workshop without questions — tolerances and finishes stated.", "score": 1}, {"id": "b", "text": "Rough sketches are enough, the workshop will figure it out.", "score": 0}, {"id": "c", "text": "I check with the fabricator early and design for how they actually make things.", "score": 1}]}, {"id": "q5", "group": "learning", "text": "A new fabrication method or material you have not used appears on a project. You…", "options": [{"id": "a", "text": "Learn it, test a sample and adopt it where it is better.", "score": 1}, {"id": "b", "text": "Avoid it and stick to what I know.", "score": 0}, {"id": "c", "text": "Study it properly before committing it to a vessel.", "score": 1}]}, {"id": "q6", "group": "team", "text": "An electrical colleague needs cutouts and cable routes in your console design. You…", "options": [{"id": "a", "text": "Design together from the start — mechanical, electrical and cooling as one assembly.", "score": 1}, {"id": "b", "text": "Finish my part first; they can adapt afterwards.", "score": 0}, {"id": "c", "text": "Agree the interfaces early and keep one shared model.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('AUT-STD-8', 'Automation engineers — PLC, SCADA & commissioning mindset (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "safety", "text": "A customer asks to bypass an interlock in the PLC so a test can run faster. You…", "options": [{"id": "a", "text": "Refuse to hide it in code; propose a documented, temporary and visible override with a return to normal.", "score": 1}, {"id": "b", "text": "Comment out the interlock and remember to put it back.", "score": 0}, {"id": "c", "text": "Explain the safety and class consequences and find a safe way to do the test.", "score": 1}]}, {"id": "q2", "group": "method", "text": "A commissioning fault does not match any documented cause. You…", "options": [{"id": "a", "text": "Reason from first principles, isolate variables and trace it methodically.", "score": 1}, {"id": "b", "text": "Swap parts until something works and move on.", "score": 0}, {"id": "c", "text": "Instrument the system, capture the data and find the cause.", "score": 1}]}, {"id": "q3", "group": "code", "text": "Your PLC code and HMI projects are…", "options": [{"id": "a", "text": "Structured, commented and versioned — the next engineer must read them without me.", "score": 1}, {"id": "b", "text": "Written to work; comments are for later.", "score": 0}, {"id": "c", "text": "Built from standard blocks with naming that matches the drawings and tag list.", "score": 1}]}, {"id": "q4", "group": "protocols", "text": "A protocol you have never used (say a new fieldbus or Modbus variant) appears on a project. You…", "options": [{"id": "a", "text": "Read the spec, build a bench test and learn it — new technology excites me.", "score": 1}, {"id": "b", "text": "Stay with what I know and avoid it where I can.", "score": 0}, {"id": "c", "text": "Test it properly before deploying it on board.", "score": 1}]}, {"id": "q5", "group": "class", "text": "Class trials of an alarm and monitoring system are tomorrow and two sensors read wrong. You…", "options": [{"id": "a", "text": "Fix them tonight, retest the channels and keep the test records ready for the surveyor.", "score": 1}, {"id": "b", "text": "Present the system as is; the surveyor may not notice.", "score": 0}, {"id": "c", "text": "Tell the project manager at once, fix what can be fixed and declare the rest openly.", "score": 1}]}, {"id": "q6", "group": "team", "text": "A colleague is stuck on something you have solved before. You…", "options": [{"id": "a", "text": "Sit with them, share what I know and write it up for the team.", "score": 1}, {"id": "b", "text": "Keep my methods to myself to stay indispensable.", "score": 0}, {"id": "c", "text": "Help right away — a stronger team delivers a better vessel.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('SRV-STD-8', 'Service engineers — on-board attitude & ownership (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "customer", "text": "You arrive on a yacht for a fault and the captain is angry about the downtime. You…", "options": [{"id": "a", "text": "Listen, explain what you will do and keep him informed until the system is back.", "score": 1}, {"id": "b", "text": "Get to work and let the office deal with him.", "score": 0}, {"id": "c", "text": "Stay calm and professional, fix the fault, then explain the cause and how to avoid it.", "score": 1}]}, {"id": "q2", "group": "method", "text": "The fault is intermittent and gone when you arrive. You…", "options": [{"id": "a", "text": "Check logs and history, reproduce it under the conditions reported and find the root cause.", "score": 1}, {"id": "b", "text": "Declare \\"no fault found\\" and leave.", "score": 0}, {"id": "c", "text": "Set up monitoring, brief the crew on what to record and follow up.", "score": 1}]}, {"id": "q3", "group": "safety", "text": "Working in a switchboard room with the vessel live, your rule is…", "options": [{"id": "a", "text": "Isolate and verify dead before touching, PPE on, permit from the chief engineer.", "score": 1}, {"id": "b", "text": "Work live when it is quicker; I know what I am doing.", "score": 0}, {"id": "c", "text": "Follow the lock-out procedure every time, even for a five-minute job.", "score": 1}]}, {"id": "q4", "group": "reporting", "text": "After the job, the service report is…", "options": [{"id": "a", "text": "Written on the day: what was found, what was done, parts used and what is still open.", "score": 1}, {"id": "b", "text": "Done later from memory, if the office insists.", "score": 0}, {"id": "c", "text": "Clear enough for the next engineer and the customer to understand without calling me.", "score": 1}]}, {"id": "q5", "group": "travel", "text": "Service work means travel to yards and ports at short notice. How does that sit with you?", "options": [{"id": "a", "text": "Part of the job — I like seeing the vessels and the places.", "score": 1}, {"id": "b", "text": "I would rather avoid travel and short-notice calls.", "score": 0}, {"id": "c", "text": "Fine, as long as it is planned fairly and I can rest between trips.", "score": 1}]}, {"id": "q6", "group": "learning", "text": "A system from a maker you do not know is on board. You…", "options": [{"id": "a", "text": "Get the manuals, call the maker if needed and learn it; next time I will know it.", "score": 1}, {"id": "b", "text": "Tell the customer we do not support it.", "score": 0}, {"id": "c", "text": "Work methodically from the documentation and record what I learn for the team.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('ACC-STD-8', 'Accounting — accuracy, controls & deadlines (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "accuracy", "text": "A supplier invoice does not match the purchase order by a small amount. You…", "options": [{"id": "a", "text": "Hold it, find the difference (price, quantity, VAT) and resolve it with procurement before posting.", "score": 1}, {"id": "b", "text": "Post it; small differences wash out.", "score": 0}, {"id": "c", "text": "Check the goods receipt and the order, then post the correct amount with a note.", "score": 1}]}, {"id": "q2", "group": "deadlines", "text": "Month-end closing falls together with VAT filing and an auditor request. You…", "options": [{"id": "a", "text": "Plan the week by legal deadline first, communicate what will land when and ask for help early.", "score": 1}, {"id": "b", "text": "Do whatever shouts loudest.", "score": 0}, {"id": "c", "text": "Work the checklist, keep the manager informed and never miss a statutory date.", "score": 1}]}, {"id": "q3", "group": "controls", "text": "A manager asks you to pay a supplier today without the approved purchase order. You…", "options": [{"id": "a", "text": "Explain the control, get the approval through the proper channel quickly, then pay.", "score": 1}, {"id": "b", "text": "Pay — the manager is responsible.", "score": 0}, {"id": "c", "text": "Escalate to the finance lead; payments follow the approval chain without exception.", "score": 1}]}, {"id": "q4", "group": "multi", "text": "Golden operates in Greece, Italy and the Netherlands. Working with several VAT regimes, currencies of invoices and branch books means…", "options": [{"id": "a", "text": "Learning each regime properly and keeping the intercompany clean.", "score": 1}, {"id": "b", "text": "Treating everything as Greek and adjusting later.", "score": 0}, {"id": "c", "text": "Keeping clear procedures per entity and checking with the local accountant when unsure.", "score": 1}]}, {"id": "q5", "group": "systems", "text": "Your attitude to the ERP and the portal (collections, payables, procurement)…", "options": [{"id": "a", "text": "Use the system as the single source of truth and improve it where it is weak.", "score": 1}, {"id": "b", "text": "Keep my own spreadsheets; systems are unreliable.", "score": 0}, {"id": "c", "text": "Learn it well and reconcile it against the bank and the ledger regularly.", "score": 1}]}, {"id": "q6", "group": "confidentiality", "text": "You see payroll and supplier terms every day. Confidentiality is…", "options": [{"id": "a", "text": "Absolute — nothing leaves the finance function, not even casually.", "score": 1}, {"id": "b", "text": "Relaxed within the office; everyone knows anyway.", "score": 0}, {"id": "c", "text": "A professional duty I take seriously, including in how I store files.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('UX-STD-8', 'UI / UX designers — users, systems & craft (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "users", "text": "You are asked to design a screen for engineers on a ship bridge. Before drawing, you…", "options": [{"id": "a", "text": "Talk to the users, understand the task, the light conditions and the glove-and-sea-state reality.", "score": 1}, {"id": "b", "text": "Start from a nice template; users adapt.", "score": 0}, {"id": "c", "text": "Study the existing screens and the class / ergonomics rules for bridge equipment.", "score": 1}]}, {"id": "q2", "group": "craft", "text": "Your relationship with design systems, spacing and typography:", "options": [{"id": "a", "text": "Consistency is the product — I build and follow a system rather than re-inventing each screen.", "score": 1}, {"id": "b", "text": "Each screen is a fresh canvas; consistency is boring.", "score": 0}, {"id": "c", "text": "I keep a component library current and document how to use it.", "score": 1}]}, {"id": "q3", "group": "feedback", "text": "An engineer says your beautiful screen is unusable in practice. You…", "options": [{"id": "a", "text": "Watch them use it, find the real problem and fix the design.", "score": 1}, {"id": "b", "text": "Defend the design; they are not designers.", "score": 0}, {"id": "c", "text": "Thank them, test with two more users and iterate.", "score": 1}]}, {"id": "q4", "group": "constraints", "text": "A screen must work on a 12-inch industrial HMI and on a phone. You…", "options": [{"id": "a", "text": "Design for the constraints — hierarchy, touch targets and contrast come first.", "score": 1}, {"id": "b", "text": "Design for the desktop and let it shrink.", "score": 0}, {"id": "c", "text": "Prototype on the real device early.", "score": 1}]}, {"id": "q5", "group": "handoff", "text": "Handing work to developers means…", "options": [{"id": "a", "text": "Specs, states, edge cases and assets ready — and staying available while they build.", "score": 1}, {"id": "b", "text": "Sending a picture; they will work it out.", "score": 0}, {"id": "c", "text": "Reviewing the built result against the design and fixing gaps together.", "score": 1}]}, {"id": "q6", "group": "learning", "text": "The tools and standards (accessibility, new design tooling) keep moving. You…", "options": [{"id": "a", "text": "Keep learning and bring what is useful into our work.", "score": 1}, {"id": "b", "text": "Stay with what I learned at school.", "score": 0}, {"id": "c", "text": "Evaluate new tools against real benefit before adopting them.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('PRD-STD-8', 'Product designers — from need to shipped product (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "discovery", "text": "A customer asks for a feature. Your first step is…", "options": [{"id": "a", "text": "Understand the problem behind the request and whether other customers share it.", "score": 1}, {"id": "b", "text": "Build exactly what was asked.", "score": 0}, {"id": "c", "text": "Write the problem statement and the success measure before any solution.", "score": 1}]}, {"id": "q2", "group": "tradeoffs", "text": "Engineering says the ideal solution takes six months; the customer needs something in six weeks. You…", "options": [{"id": "a", "text": "Find the smallest version that solves the real problem and plan the rest.", "score": 1}, {"id": "b", "text": "Push engineering to do it all in six weeks.", "score": 0}, {"id": "c", "text": "Agree the scope cut openly with both sides and record it.", "score": 1}]}, {"id": "q3", "group": "evidence", "text": "How do you know a product decision was right?", "options": [{"id": "a", "text": "By a measure defined up front and checked after release.", "score": 1}, {"id": "b", "text": "If nobody complains.", "score": 0}, {"id": "c", "text": "By user feedback and usage data reviewed together with the team.", "score": 1}]}, {"id": "q4", "group": "domain", "text": "Our products live in marine automation, energy storage and shipyard operations. Domain knowledge is…", "options": [{"id": "a", "text": "Essential — I learn the vessels, the rules and the users to design well.", "score": 1}, {"id": "b", "text": "Not needed; design is design.", "score": 0}, {"id": "c", "text": "Something I build fast by spending time with engineers and customers.", "score": 1}]}, {"id": "q5", "group": "collab", "text": "Working with electrical and software engineers means…", "options": [{"id": "a", "text": "Shared ownership of the outcome — I bring the user, they bring feasibility.", "score": 1}, {"id": "b", "text": "I design, they implement.", "score": 0}, {"id": "c", "text": "Early and frequent review so nothing surprises anyone late.", "score": 1}]}, {"id": "q6", "group": "quality", "text": "A release is ready but has a known rough edge in a rarely used flow. You…", "options": [{"id": "a", "text": "Ship, document it openly and schedule the fix — perfect is the enemy of delivered.", "score": 1}, {"id": "b", "text": "Hide it and hope nobody finds it.", "score": 0}, {"id": "c", "text": "Judge by the risk to users; fix it first if it can mislead or harm.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('SAL-STD-8', 'Sales engineers — technical credibility & honest selling (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "honesty", "text": "A customer asks whether our system can do something it cannot do today. You…", "options": [{"id": "a", "text": "Say so plainly, explain what it can do and how the gap could be closed.", "score": 1}, {"id": "b", "text": "Say yes and let engineering figure it out.", "score": 0}, {"id": "c", "text": "Offer the realistic alternative and keep the trust for the next project.", "score": 1}]}, {"id": "q2", "group": "technical", "text": "Preparing an offer for a switchboard and automation scope, you…", "options": [{"id": "a", "text": "Read the specification and the class requirements, and check the scope with the engineers before pricing.", "score": 1}, {"id": "b", "text": "Copy the last offer and change the name.", "score": 0}, {"id": "c", "text": "Build the scope boundary clearly — what we supply, what the yard supplies.", "score": 1}]}, {"id": "q3", "group": "process", "text": "Your relationship with the pipeline and CRM:", "options": [{"id": "a", "text": "Every lead, offer and follow-up is recorded — the team and the forecast depend on it.", "score": 1}, {"id": "b", "text": "I keep it in my head and my inbox.", "score": 0}, {"id": "c", "text": "Updated weekly with next steps and realistic probabilities.", "score": 1}]}, {"id": "q4", "group": "negotiation", "text": "A yard pushes for a 20 % discount or they go elsewhere. You…", "options": [{"id": "a", "text": "Understand what they really need, defend the value and trade scope or terms rather than just price.", "score": 1}, {"id": "b", "text": "Give the discount to win it.", "score": 0}, {"id": "c", "text": "Involve management with the numbers and a recommendation.", "score": 1}]}, {"id": "q5", "group": "relationship", "text": "After the order is signed, the customer relationship is…", "options": [{"id": "a", "text": "Just starting — I stay involved through delivery and warranty because that wins the next order.", "score": 1}, {"id": "b", "text": "The project manager''s problem.", "score": 0}, {"id": "c", "text": "Reviewed regularly for satisfaction and new opportunities.", "score": 1}]}, {"id": "q6", "group": "learning", "text": "Our products and the rules change (class, energy storage, shore power). You…", "options": [{"id": "a", "text": "Keep current — a sales engineer who cannot discuss the technology is just a salesman.", "score": 1}, {"id": "b", "text": "Rely on the engineers for the technical talk.", "score": 0}, {"id": "c", "text": "Attend the trainings and read the standards that matter to our customers.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('PRC-STD-8', 'Procurement — cost, lead time & integrity (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "leadtime", "text": "A project needs a breaker with a 14-week lead time and the plan has 6 weeks. You…", "options": [{"id": "a", "text": "Search for an equivalent accepted by class, check stock at distributors and report the options with prices the same day.", "score": 1}, {"id": "b", "text": "Order it and let the project manager find out.", "score": 0}, {"id": "c", "text": "Raise it immediately and propose the alternatives with their trade-offs.", "score": 1}]}, {"id": "q2", "group": "cost", "text": "The cheapest quote comes from a supplier you do not know. You…", "options": [{"id": "a", "text": "Qualify them (references, certificates, delivery record) before awarding; the cheapest late part is the most expensive.", "score": 1}, {"id": "b", "text": "Award it — price is what counts.", "score": 0}, {"id": "c", "text": "Compare total cost: price, freight, lead time, warranty and risk.", "score": 1}]}, {"id": "q3", "group": "integrity", "text": "A supplier offers you a personal gift to be preferred on the next order. You…", "options": [{"id": "a", "text": "Decline and report it; supplier selection is on merit only.", "score": 1}, {"id": "b", "text": "Accept it — it does not influence me.", "score": 0}, {"id": "c", "text": "Decline politely and keep the relationship strictly professional.", "score": 1}]}, {"id": "q4", "group": "process", "text": "Requisitions, requests for offer, purchase orders and goods receipts in the portal are…", "options": [{"id": "a", "text": "The record of truth — every purchase goes through them so stock, costs and payables stay right.", "score": 1}, {"id": "b", "text": "Paperwork I complete afterwards when there is time.", "score": 0}, {"id": "c", "text": "Kept current daily so the project managers see real status.", "score": 1}]}, {"id": "q5", "group": "suppliers", "text": "Your view of supplier relationships:", "options": [{"id": "a", "text": "Long-term partners who deliver on time deserve loyalty, but every award is still competitive.", "score": 1}, {"id": "b", "text": "Change supplier every time for the last euro.", "score": 0}, {"id": "c", "text": "Few, well-qualified suppliers per category, reviewed yearly.", "score": 1}]}, {"id": "q6", "group": "learning", "text": "Marine components, class certificates and export rules are specialised. You…", "options": [{"id": "a", "text": "Learn the products and the rules — a buyer who understands the parts buys better.", "score": 1}, {"id": "b", "text": "Leave the technical side to engineers.", "score": 0}, {"id": "c", "text": "Ask the engineers and build my own knowledge of the catalogue.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]'),
('SAS-STD-8', 'Sales assistants — organisation, accuracy & customer care (8 questions)', 7, 'loyalty', '[{"id": "q1", "group": "accuracy", "text": "An offer document goes to a customer with the wrong vessel name. You…", "options": [{"id": "a", "text": "Correct it at once, apologise briefly and add a check so it does not happen again.", "score": 1}, {"id": "b", "text": "Leave it; they will understand.", "score": 0}, {"id": "c", "text": "Fix it and review how the template is filled.", "score": 1}]}, {"id": "q2", "group": "organisation", "text": "Three salespeople ask you for offers, a trade-fair booking and a customer visit — all for tomorrow. You…", "options": [{"id": "a", "text": "Clarify the deadlines, agree priorities with them and say what will be ready when.", "score": 1}, {"id": "b", "text": "Do whatever came in last.", "score": 0}, {"id": "c", "text": "Plan the day, keep everyone informed and deliver what was promised.", "score": 1}]}, {"id": "q3", "group": "customer", "text": "A customer calls with a complaint while the salesperson is travelling. You…", "options": [{"id": "a", "text": "Take ownership: listen, record it, give a timeframe and make sure someone answers.", "score": 1}, {"id": "b", "text": "Ask them to call back next week.", "score": 0}, {"id": "c", "text": "Resolve what I can, escalate the rest and confirm to the customer.", "score": 1}]}, {"id": "q4", "group": "systems", "text": "The CRM / pipeline, the offers register and the customer records are…", "options": [{"id": "a", "text": "Kept accurate and current — the sales team and management work from them.", "score": 1}, {"id": "b", "text": "Updated when someone asks.", "score": 0}, {"id": "c", "text": "My responsibility to keep clean and complete.", "score": 1}]}, {"id": "q5", "group": "confidentiality", "text": "You handle prices, margins and customer contacts. Confidentiality means…", "options": [{"id": "a", "text": "Nothing shared outside the team, careful with files and e-mail.", "score": 1}, {"id": "b", "text": "Normal office talk; everyone knows the prices anyway.", "score": 0}, {"id": "c", "text": "A professional duty I take seriously.", "score": 1}]}, {"id": "q6", "group": "learning", "text": "Our products are technical (automation, electrical systems, energy storage). You…", "options": [{"id": "a", "text": "Learn enough to speak to customers sensibly and route questions correctly.", "score": 1}, {"id": "b", "text": "Do not need to understand them.", "score": 0}, {"id": "c", "text": "Ask the engineers and build a glossary for myself.", "score": 1}]}, {"id": "q7", "group": "loyalty", "text": "Looking back at your roles, what best describes your typical tenure?", "options": [{"id": "a", "text": "Several years each — I commit and see things through.", "score": 1}, {"id": "b", "text": "Long tenures, with moves driven by genuine growth, not restlessness.", "score": 1}, {"id": "c", "text": "Often under a year — I tend to move on quickly and frequently.", "score": 0}]}, {"id": "q8", "group": "loyalty", "text": "Golden invests in its people (training, certifications, real responsibility). What would make you stay long-term?", "options": [{"id": "a", "text": "Interesting work, a team I respect and room to grow.", "score": 1}, {"id": "b", "text": "Whatever pays most at any given moment; I would leave the day a better offer appears.", "score": 0}, {"id": "c", "text": "The company investing in my development and a clear path forward.", "score": 1}]}]');
